import{_ as n,o as i,c as t,a2 as a}from"./chunks/framework.Bzd4OF_4.js";const u=JSON.parse('{"title":"Learning notes and design decisions","description":"","frontmatter":{},"headers":[],"relativePath":"learning-notes.md","filePath":"learning-notes.md"}'),s={name:"learning-notes.md"};function o(r,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="learning-notes-and-design-decisions" tabindex="-1">Learning notes and design decisions <a class="header-anchor" href="#learning-notes-and-design-decisions" aria-label="Permalink to &quot;Learning notes and design decisions&quot;">​</a></h1><p>TALLY is intentionally built as a learning project. The useful unit of progress is a repeatable vertical slice: domain behavior, persistence, API, interface, authorization, tests, observability, and recovery evidence.</p><p>Selected lessons:</p><ul><li>A modular monolith keeps ownership visible while avoiding premature distributed-systems cost.</li><li>Exact money and immutable corrections are foundational decisions, not late hardening.</li><li>Shared abstractions should follow repeated concrete use; foundational identity, money, scope, idempotency, and evidence primitives are the exception.</li><li>Local development is the default, while Azure exercises deployment and recovery concerns without implying production qualification.</li></ul><p>Architecture decisions and their rationale remain in the <a href="https://github.com/toanle88/Tally/tree/main/docs/specs/system_design" target="_blank" rel="noreferrer">system design documents</a>.</p>',5)])])}const h=n(s,[["render",o]]);export{u as __pageData,h as default};
